// Font families per language for Indic scripts
const LANGUAGE_FONTS: Record<Language, string> = {
  en: "'Inter', 'Inter Tight', sans-serif",
  ar: "'Noto Sans Arabic', 'Inter', sans-serif",
  te: "'Noto Sans Telugu', 'Inter', sans-serif",
  hi: "'Noto Sans Devanagari', 'Inter', sans-serif",
  kn: "'Noto Sans Kannada', 'Inter', sans-serif",
  ta: "'Noto Sans Tamil', 'Inter', sans-serif",
  ml: "'Noto Sans Malayalam', 'Inter', sans-serif",
  mr: "'Noto Sans Devanagari', 'Inter', sans-serif",
};

const LANGUAGE_LABELS: Record<Language, string> = {
  en: "EN",
  ar: "عر",
  te: "తె",
  hi: "हि",
  kn: "ಕ",
  ta: "த",
  ml: "മ",
  mr: "म",
};

export { LANGUAGE_LABELS };

const VALID_LANGUAGES: Language[] = ["en", "ar", "te", "hi", "kn", "ta", "ml", "mr"];

const defaultValue: I18nContextType = {
  language: "en",
  direction: "ltr",
  setLanguage: () => { },
  t: (key: string, fallback?: string) => fallback || key,
};

const I18nContext = createContext<I18nContextType>(defaultValue);

export function I18nProvider({ children }: { children: React.ReactNode }) {
  const [language, setLanguageState] = useState<Language>(() => {
    if (typeof window === "undefined") return "en";
    try {
      const saved = localStorage.getItem("bos-lang") as Language;
      return VALID_LANGUAGES.includes(saved) ? saved : "en";
    } catch {
      return "en";
    }
  });

  const direction: Direction = language === "ar" ? "rtl" : "ltr";

  useEffect(() => {
    if (typeof window === "undefined") return;
    try {
      document.documentElement.dir = direction;
      document.documentElement.lang = language;
      localStorage.setItem("bos-lang", language);

      // RTL class
      if (language === "ar") {
        document.documentElement.classList.add("rtl");
      } else {
        document.documentElement.classList.remove("rtl");
      }

      // Apply font family for Indic scripts
      document.documentElement.style.setProperty(
        "--font-sans",
        LANGUAGE_FONTS[language]
      );

      // Inject Google Fonts link for Indic scripts dynamically
      const fontLinks: Record<string, string> = {
        te: "https://fonts.googleapis.com/css2?family=Noto+Sans+Telugu:wght@300..900&display=swap",
        hi: "https://fonts.googleapis.com/css2?family=Noto+Sans+Devanagari:wght@300..900&display=swap",
        kn: "https://fonts.googleapis.com/css2?family=Noto+Sans+Kannada:wght@300..900&display=swap",
        ar: "https://fonts.googleapis.com/css2?family=Noto+Sans+Arabic:wght@300..900&display=swap",
        ta: "https://fonts.googleapis.com/css2?family=Noto+Sans+Tamil:wght@300..900&display=swap",
        ml: "https://fonts.googleapis.com/css2?family=Noto+Sans+Malayalam:wght@300..900&display=swap",
        mr: "https://fonts.googleapis.com/css2?family=Noto+Sans+Devanagari:wght@300..900&display=swap",
      };

      if (fontLinks[language]) {
        const linkId = `bos-font-${language}`;
        if (!document.getElementById(linkId)) {
          const link = document.createElement("link");
          link.id = linkId;
          link.rel = "stylesheet";
          link.href = fontLinks[language];
          document.head.appendChild(link);
        }
      }
    } catch (e) {
      console.error("Failed to update document direction:", e);
    }
  }, [language, direction]);

  const setLanguage = (lang: Language) => {
    setLanguageState(lang);
  };

    // Pre-normalized map for fast case-insensitive lookup
  const t = (key: string, fallback?: string): string => {
    if (!key) return fallback || "";
    const langDict = translations[language] || translations.en;
    
    // 1. Direct match
    if (langDict[key]) return langDict[key];
    
    // 2. Trimmed match
    const trimmed = key.trim();
    if (langDict[trimmed]) return langDict[trimmed];
    
    // 3. Exact English dictionary lookup
    if (translations.en[key]) {
      const enVal = translations.en[key];
      if (langDict[enVal]) return langDict[enVal];
    }
    if (translations.en[trimmed]) {
      const enVal = translations.en[trimmed];
      if (langDict[enVal]) return langDict[enVal];
    }

    // 4. Case-insensitive lookup against current language dictionary
    const lowerKey = trimmed.toLowerCase();
    for (const [k, v] of Object.entries(langDict)) {
      if (k.toLowerCase() === lowerKey) return v;
    }

    // 5. Case-insensitive lookup against English dictionary then mapped to current language
    for (const [k, v] of Object.entries(translations.en)) {
      if (k.toLowerCase() === lowerKey) {
        if (langDict[v]) return langDict[v];
        if (langDict[k]) return langDict[k];
      }
    }

    // 6. Return provided fallback or original key
    if (fallback) return fallback;
    return key;
  };


  // ── High-Performance Global UI Chrome Auto-Translator ────────────
  useEffect(() => {
    if (typeof window === "undefined") return;

    const translateDomElements = () => {
      // 1. Selectable UI chrome elements
      const selector = "h1, h2, h3, h4, h5, h6, button, th, label, p.text-muted-foreground, p.text-slate-500, p.text-slate-600, span.text-muted-foreground, [data-i18n-auto]";
      const elements = document.querySelectorAll<HTMLElement>(selector);

      elements.forEach((el) => {
        // Skip user dynamic data containers
        if (el.closest("td") || el.closest("[data-no-translate='true']") || el.closest("pre") || el.closest("code")) return;
        
        // Handle direct text content for simple elements (leaf nodes or buttons with icons)
        if (el.childElementCount <= 2) {
          const firstChild = el.childNodes[el.childNodes.length - 1];
          const textNode = Array.from(el.childNodes).find(n => n.nodeType === Node.TEXT_NODE && n.textContent && n.textContent.trim().length > 1);
          
          if (textNode && textNode.textContent) {
            const raw = textNode.textContent.trim();
            if (!(el as any).__i18n_orig_text) {
              (el as any).__i18n_orig_text = raw;
            }
            const orig = (el as any).__i18n_orig_text;
            if (language === "en") {
              if (textNode.textContent.trim() !== orig) {
                textNode.textContent = textNode.textContent.replace(textNode.textContent.trim(), orig);
              }
            } else {
              const translated = t(orig);
              if (translated && translated !== orig) {
                textNode.textContent = textNode.textContent.replace(textNode.textContent.trim(), translated);
              }
            }
          }
        }
      });

      // 2. Translate Input and Textarea placeholders
      const inputs = document.querySelectorAll<HTMLInputElement | HTMLTextAreaElement>("input[placeholder], textarea[placeholder]");
      inputs.forEach((input) => {
        if (input.closest("[data-no-translate='true']")) return;
        const currentPh = input.placeholder;
        if (!currentPh) return;
        if (!(input as any).__i18n_orig_ph) {
          (input as any).__i18n_orig_ph = currentPh;
        }
        const orig = (input as any).__i18n_orig_ph;
        if (language === "en") {
          input.placeholder = orig;
        } else {
          const translated = t(orig);
          if (translated && translated !== orig) {
            input.placeholder = translated;
          }
        }
      });
    };

    // Run immediately on render / language change
    translateDomElements();

    // Observe dynamic tab switches and route changes
    const observer = new MutationObserver(() => {
      translateDomElements();
    });

    observer.observe(document.body, {
      childList: true,
      subtree: true,
      characterData: false,
    });

    return () => {
      observer.disconnect();
    };
  }, [language, t]);


  // ── High-Performance Global UI Chrome Auto-Translator ────────────
  useEffect(() => {
    if (typeof window === "undefined") return;

    const translateDomElements = () => {
      // 1. Selectable UI chrome elements
      const selector = "h1, h2, h3, h4, h5, h6, button, th, label, p.text-muted-foreground, p.text-slate-500, p.text-slate-600, span.text-muted-foreground, [data-i18n-auto]";
      const elements = document.querySelectorAll<HTMLElement>(selector);

      elements.forEach((el) => {
        // Skip user dynamic data containers
        if (el.closest("td") || el.closest("[data-no-translate='true']") || el.closest("pre") || el.closest("code")) return;
        
        // Handle direct text content for simple elements (leaf nodes or buttons with icons)
        if (el.childElementCount <= 2) {
          const firstChild = el.childNodes[el.childNodes.length - 1];
          const textNode = Array.from(el.childNodes).find(n => n.nodeType === Node.TEXT_NODE && n.textContent && n.textContent.trim().length > 1);
          
          if (textNode && textNode.textContent) {
            const raw = textNode.textContent.trim();
            if (!(el as any).__i18n_orig_text) {
              (el as any).__i18n_orig_text = raw;
            }
            const orig = (el as any).__i18n_orig_text;
            if (language === "en") {
              if (textNode.textContent.trim() !== orig) {
                textNode.textContent = textNode.textContent.replace(textNode.textContent.trim(), orig);
              }
            } else {
              const translated = t(orig);
              if (translated && translated !== orig) {
                textNode.textContent = textNode.textContent.replace(textNode.textContent.trim(), translated);
              }
            }
          }
        }
      });

      // 2. Translate Input and Textarea placeholders
      const inputs = document.querySelectorAll<HTMLInputElement | HTMLTextAreaElement>("input[placeholder], textarea[placeholder]");
      inputs.forEach((input) => {
        if (input.closest("[data-no-translate='true']")) return;
        const currentPh = input.placeholder;
        if (!currentPh) return;
        if (!(input as any).__i18n_orig_ph) {
          (input as any).__i18n_orig_ph = currentPh;
        }
        const orig = (input as any).__i18n_orig_ph;
        if (language === "en") {
          input.placeholder = orig;
        } else {
          const translated = t(orig);
          if (translated && translated !== orig) {
            input.placeholder = translated;
          }
        }
      });
    };

    // Run immediately on render / language change
    translateDomElements();

    // Observe dynamic tab switches and route changes
    const observer = new MutationObserver(() => {
      translateDomElements();
    });

    observer.observe(document.body, {
      childList: true,
      subtree: true,
      characterData: false,
    });

    return () => {
      observer.disconnect();
    };
  }, [language, t]);

  return (
    <I18nContext.Provider value={{ language, direction, setLanguage, t }}>
      {children}
    </I18nContext.Provider>
  );
}

export function useI18n() {
  return useContext(I18nContext);
}
